using System;
using System.IO;
using System.Linq;
namespace Touchfish {
public partial class PanelWindow {
 public void PreviewPriestScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;Check(catalog.Deckable(catalog.Pool("classic-2014")).Where(c=>c.CardClass=="PRIEST").All(matchRules.Supports),"All Priest cards enabled in builder");VerifyPriestTcp(folder);File.WriteAllText(Path.Combine(folder,"priest-verification.txt"),"PASS: "+(checks-before)+" focused Priest assertions; host authority, private copies, battlecry placement, hero power replacement and actual loopback TCP.");}
 void VerifyPriestTcp(string folder){if(!VerificationRun.Network)return;LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetFullEffects(false);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyTheme(true,true);guest.ApplyMode(false);try{
  lanPort.Text=FreeLanPort().ToString();lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="PRIEST");BeginLan(true);guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="WARRIOR");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Priest TCP peers connect");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Host mulligan reaches guest");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"Both mulligans complete");var g=lanAuthority.Game;foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();}g.Players[0].Mana=g.Players[0].MaxMana=10;Inject(g,"EX1_398",1);int vision=Inject(g,"CS2_003");PublishLan();BeginCard(vision);PumpLan(()=>guest.match.Players[0].HandCount==1,"Mind Vision public count synchronizes");Check(guest.match.Players[0].Hand.Count==0&&match.Players[0].Hand.Single().Generated&&g.Players[1].Hand.Count==1,"Copied identity stays private and opponent hand unchanged");var copy=match.Players[0].Hand.Single();BeginCard(copy.Id);ClickEmptySlot(0,0);PumpLan(()=>guest.match.Players[0].Board.Any(u=>u.CardId=="VAN_EX1_398"),"Foreign copied minion playable and public after summon");
  g.Players[0].Mana=g.Players[0].MaxMana=10;var enemy=g.Summon(1,"VAN_CS2_231");int cabal=Inject(g,"EX1_091");PublishLan();BeginCard(cabal);ClickEmptySlot(0,1);Check(pending=="play"&&pendingPosition==1,"Cabal waits for target after placement");ClickMatchTarget(new MatchTarget(1,enemy.Id));PumpLan(()=>guest.match.Players[0].Board.Any(u=>u.Id==enemy.Id),"Cabal authority transfers control");Check(g.Players[0].Board.Count==3&&guest.match.Players[1].Board.Count==0,"Both clients agree on stolen minion ownership");
  g.Players[0].Mana=g.Players[0].MaxMana=10;int form=Inject(g,"EX1_625");PublishLan();BeginCard(form);PumpLan(()=>guest.match.Players[0].Shadowform==1,"Shadowform state synchronizes");BeginPower();ClickMatchTarget(new MatchTarget(1));PumpLan(()=>guest.match.Players[1].Health==28,"Shadowform power deals two on authority");Check(guest.match.PowerLabel(0)=="心灵尖刺"&&match.Players[0].PowerUsed,"Power text and usage match between peers");Render(Path.Combine(folder,"129-priest-shadowform-codex.png"));
  DoMatch("end");PumpLan(()=>guest.match.Active==1,"Guest turn starts");g.Players[1].Mana=g.Players[1].MaxMana=10;int guestForm=Inject(g,"EX1_625",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==guestForm),"Foreign Shadowform reaches private guest hand");guest.BeginCard(guestForm);PumpLan(()=>!guest.lanWaiting&&g.Players[1].Shadowform==1,"Guest replaces foreign hero power");guest.BeginPower();guest.ClickMatchTarget(new MatchTarget(0));PumpLan(()=>!guest.lanWaiting&&g.Players[0].Health==28,"Guest transformed power uses target flow");Check(match.Players[1].Shadowform==1&&guest.match.Players[0].Hand.Count==0,"Guest power replacement does not expose opponent hand");
 }finally{guest.LeaveLan();guest.Close();LeaveLan();}}
}
}
